// Scratch review probe (deleted after the run) — NOT part of the PR.
//
// Reproduces the mounted-session path resolution semantics with the exact
// rig file_browser_test.dart uses, to check whether a file open / upload
// from INSIDE a mounted subfolder resolves (the _childPath sub-branch).
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('probe: bare subpath vs /project-prefixed subpath at a live mount', () async {
    final base = MemoryExecutionEnv(cwd: '/app-sandbox');
    await base.writeFile('/Users/x/support/src/nested.txt', 'body');
    final env = ProjectMountEnv(base)..mountedRoot = '/Users/x/support';

    // What _childPath returns in a subfolder (segments = ['src']):
    final bare = await env.readBinaryFile('src/nested.txt');
    // What the fixed _envPath returns for the same folder listing:
    final prefixed = await env.readBinaryFile('/project/src/nested.txt');

    // ignore: avoid_print
    print('bare src/nested.txt        → ok=${bare.isOk} '
        '${bare.isErr ? bare.errorOrNull!.code : ''}');
    // ignore: avoid_print
    print('/project/src/nested.txt    → ok=${prefixed.isOk} '
        '${prefixed.isErr ? prefixed.errorOrNull!.code : ''}');

    // Upload path: writeBinaryFile(_childPath(name)) from a subfolder.
    final write = await env.writeBinaryFile(
      'src/uploaded.txt',
      Uint8List.fromList('x'.codeUnits),
    );
    final landedInMount = await base.exists('/Users/x/support/src/uploaded.txt');
    final landedInContainer = await base.exists('/app-sandbox/src/uploaded.txt');
    // ignore: avoid_print
    print('upload write ok=${write.isOk} landedInMount=$landedInMount '
        'landedInContainer=$landedInContainer');

    expect(prefixed.isOk, isTrue);
  });
}

