import 'package:flutter_test/flutter_test.dart';

Widget _wrap(Widget child) => MaterialApp(home: Scaffold(body: child));

void main() {
  testWidgets('gh-2131 probe: opening a file INSIDE a mounted subfolder', (tester) async {
    final base = MemoryExecutionEnv(cwd: '/app-sandbox');
    await base.writeFile('/Users/x/support/src/nested.txt', 'subfolder body');
    final env = ProjectMountEnv(base)..mountedRoot = '/Users/x/support';
    await tester.pumpWidget(_wrap(FileBrowser(
      env: env,
      initialPath: visibleFolderRoot(env, '/Users/x/support'),
      sessionFolder: '/Users/x/support',
    )));
    await tester.pumpAndSettle();
    await tester.tap(find.text('src')); // drill down
    await tester.pumpAndSettle();
    expect(find.text('nested.txt'), findsOneWidget); // listing works post-fix
    await tester.tap(find.text('nested.txt')); // open the file
    await tester.pumpAndSettle();
    final err = find.text('Could not load file');
    // ignore: avoid_print
    print('SUBFOLDER-OPEN error-shown=${err.evaluate().isNotEmpty} '
        'body-shown=${find.text('subfolder body').evaluate().isNotEmpty}');
  });
}
